-- Daily Best Picks table
-- Stores pre-computed daily picks generated by scripts/daily_best_picks.py
-- Run in Supabase SQL Editor

CREATE TABLE IF NOT EXISTS daily_picks (
    id              BIGSERIAL PRIMARY KEY,
    generated_date  DATE NOT NULL,
    player          TEXT NOT NULL,
    player_id       INTEGER,
    team_abbrev     TEXT,
    stat            TEXT NOT NULL,           -- PTS, REB, AST, PRA
    prediction      FLOAT NOT NULL,
    confidence      FLOAT,
    range_low       FLOAT,
    range_high      FLOAT,
    recent_avg      FLOAT,                  -- L10 avg (proxy line)
    odds_line       FLOAT,                  -- NULL until new OddsAPI key
    edge            FLOAT,
    direction       TEXT NOT NULL,
    opponent        TEXT,
    is_home         BOOLEAN DEFAULT false,
    matchup         TEXT,
    game_date       TEXT,
    model_type      TEXT DEFAULT 'gradient_boost',
    prob_over       FLOAT,
    rank            INTEGER,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Fast lookup by date + rank
CREATE INDEX IF NOT EXISTS idx_daily_picks_date_rank
    ON daily_picks(generated_date, rank);

-- Prevent duplicate player+stat combos for the same day
CREATE UNIQUE INDEX IF NOT EXISTS idx_daily_picks_unique
    ON daily_picks(generated_date, player_id, stat);

-- Row-Level Security: everyone can read, only service role can write
ALTER TABLE daily_picks ENABLE ROW LEVEL SECURITY;

CREATE POLICY "daily_picks_public_read"
    ON daily_picks FOR SELECT USING (true);

CREATE POLICY "daily_picks_service_write"
    ON daily_picks FOR ALL USING (auth.role() = 'service_role');
